import{_ as n,a0 as l,w as r,s as p,I as t,x as o,a1 as i,A as s,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"命令行快速提示：权限进阶 | LCTT x X-CMD","titleTemplate":false,"description":"命令行快速提示：权限进阶 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行快速提示：权限进阶 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行快速提示：权限进阶 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190729 Command line quick tips- More about permissions","title":"命令行快速提示：权限进阶","tag":"201908","desc":""},"relativePath":"201908/20190729 Command line quick tips- More about permissions.md","filePath":"[post].md"}'),c={name:"201908/20190729 Command line quick tips- More about permissions.md"};function u(g,e,m,f,h,k){const d=l("Link");return r(),p("div",null,[e[23]||(e[23]=t("h1",{id:"命令行快速提示-权限进阶",tabindex:"-1"},[o("命令行快速提示：权限进阶 "),t("a",{class:"header-anchor",href:"#命令行快速提示-权限进阶","aria-label":"Permalink to “命令行快速提示：权限进阶”"},"​")],-1)),e[24]||(e[24]=t("p",null,[t("img",{src:"https://fedoramagazine.org/wp-content/uploads/2018/10/commandlinequicktips-816x345.jpg",alt:""})],-1)),t("p",null,[e[2]||(e[2]=o("前一篇文章",-1)),i(d,{href:"https://linux.cn/article-11123-1.html"},{default:s(()=>[...e[0]||(e[0]=[o("介绍了 Fedora 系统上有关文件权限的一些基础知识",-1)])]),_:1}),e[3]||(e[3]=o("。本部分介绍使用权限管理文件访问和共享的其他方法。它建立在前一篇文章中的知识和示例的基础上，所以如果你还没有阅读过那篇文章，请",-1)),i(d,{href:"https://linux.cn/article-11123-1.html"},{default:s(()=>[...e[1]||(e[1]=[o("查看",-1)])]),_:1}),e[4]||(e[4]=o("它。",-1))]),e[25]||(e[25]=a('<h3 id="符号与八进制" tabindex="-1">符号与八进制 <a class="header-anchor" href="#符号与八进制" aria-label="Permalink to “符号与八进制”">​</a></h3><p>在上一篇文章中，你了解到文件有三个不同的权限集。拥有该文件的用户有一个集合，拥有该文件的组的成员有一个集合，然后最终一个集合适用于其他所有人。在长列表（<code>ls -l</code>）中这些权限使用符号模式显示在屏幕上。</p><p>每个集合都有 <code>r</code>、<code>w</code> 和 <code>x</code> 条目，表示特定用户（所有者、组成员或其他）是否可以读取、写入或执行该文件。但是还有另一种表达这些权限的方法：八进制模式。</p>',3)),t("p",null,[e[6]||(e[6]=o("你已经习惯了",-1)),i(d,{href:"https://en.wikipedia.org/wiki/Decimal"},{default:s(()=>[...e[5]||(e[5]=[o("十进制",-1)])]),_:1}),e[7]||(e[7]=a("编号系统，它有十个不同的值（<code>0</code> 到 <code>9</code>）。另一方面，八进制系统有八个不同的值（<code>0</code> 到 <code>7</code>）。在表示权限时，八进制用作速记来显示 <code>r</code>、<code>w</code> 和 <code>x</code> 字段的值。将每个字段视为具有如下值：",15))]),e[26]||(e[26]=a(`<ul><li><code>r</code> = 4</li><li><code>w</code> = 2</li><li><code>x</code> = 1</li></ul><p>现在，你可以使用单个八进制值表达任何组合。例如，读取和写入权限（但没有执行权限）的值为 <code>6</code>。读取和执行权限的值仅为 <code>5</code>。文件的 <code>rwxr-xr-x</code> 符号权限的八进制值为 <code>755</code>。</p><p>与符号值类似，你可以使用八进制值使用 <code>chmod</code> 命令设置文件权限。以下两个命令对文件设置相同的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod u=rw,g=r,o=r myfile1</span></span>
<span class="line"><span>chmod 644 myfile1</span></span></code></pre></div><h3 id="特殊权限位" tabindex="-1">特殊权限位 <a class="header-anchor" href="#特殊权限位" aria-label="Permalink to “特殊权限位”">​</a></h3><p>文件上还有几个特殊权限位。这些被称为 <code>setuid</code>（或 <code>suid</code>）、<code>setgid</code>（或 <code>sgid</code>），以及<ruby>粘滞位<rt>sticky bit</rt></ruby>（或<ruby>阻止删除位<rt>delete inhibit</rt></ruby>）。 将此视为另一组八进制值：</p><ul><li><code>setuid</code> = 4</li><li><code>setgid</code> = 2</li><li><code>sticky</code> = 1</li></ul><p><strong>除非</strong>该文件是可执行的，否则 <code>setuid</code> 位是被忽略的。如果是可执行的这种情况，则该文件（可能是应用程序或脚本）的运行就像拥有该文件的用户启动的一样。<code>setuid</code> 的一个很好的例子是 <code>/bin/passwd</code> 实用程序，它允许用户设置或更改密码。此实用程序必须能够写入到不允许普通用户更改的文件中（LCTT 译注：此处是指 <code>/etc/passwd</code> 和 <code>/etc/shadow</code>）。因此它需要精心编写，由 <code>root</code> 用户拥有，并具有 <code>setuid</code> 位，以便它可以更改密码相关文件。</p><p><code>setgid</code> 位对于可执行文件的工作方式类似。该文件将使用拥有它的组的权限运行。但是，<code>setgid</code> 对于目录还有一个额外的用途。如果在具有 <code>setgid</code> 权限的目录中创建文件，则该文件的组所有者将设置为该目录的组所有者。</p><p>最后，虽然文件粘滞位没有意义会被忽略，但它对目录很有用。在目录上设置的粘滞位将阻止用户删除其他用户拥有的该目录中的文件。</p><p>在八进制模式下使用 <code>chmod</code> 设置这些位的方法是添加一个值前缀，例如 <code>4755</code>，可以将 <code>setuid</code> 添加到可执行文件中。在符号模式下，<code>u</code> 和 <code>g</code> 也可用于设置或删除 <code>setuid</code> 和 <code>setgid</code>，例如 <code>u+s,g+s</code>。粘滞位使用 <code>o+t</code> 设置。（其他的组合，如 <code>o+s</code> 或 <code>u+t</code>，是没有意义的，会被忽略。）</p><h3 id="共享与特殊权限" tabindex="-1">共享与特殊权限 <a class="header-anchor" href="#共享与特殊权限" aria-label="Permalink to “共享与特殊权限”">​</a></h3><p>回想一下前一篇文章中关于需要共享文件的财务团队的示例。可以想象，特殊权限位有助于更有效地解决问题。原来的解决方案只是创建了一个整个组可以写入的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwx---. 2 root finance 4096 Jul  6 15:35 finance</span></span></code></pre></div><p>此目录的一个问题是，<code>finance</code> 组成员的用户 <code>dwayne</code> 和 <code>jill</code> 可以删除彼此的文件。这对于共享空间来说不是最佳选择。它在某些情况下可能有用，但在处理财务记录时可能不会！</p><p>另一个问题是此目录中的文件可能无法真正共享，因为它们将由 <code>dwayne</code> 和 <code>jill</code> 的默认组拥有 - 很可能用户私有组也命名为 <code>dwayne</code> 和 <code>jill</code>，而不是 <code>finance</code>。</p><p>解决此问题的更好方法是在文件夹上设置 <code>setgid</code> 和粘滞位。这将做两件事：使文件夹中创建的文件自动归 <code>finance</code> 组所有，并防止 <code>dwayne</code> 和 <code>jill</code> 删除彼此的文件。下面这些命令中的任何一个都可以工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo chmod 3770 finance</span></span>
<span class="line"><span>sudo chmod u+rwx,g+rwxs,o+t finance</span></span></code></pre></div><p>该文件的长列表现在显示了所应用的新特殊权限。粘滞位显示为 <code>T</code> 而不是 <code>t</code>，因为 <code>finance</code> 组之外的用户无法搜索该文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrws--T. 2 root finance 4096 Jul  6 15:35 finance</span></span></code></pre></div><hr>`,21)),t("p",null,[e[9]||(e[9]=o("via: ",-1)),i(d,{href:"https://fedoramagazine.org/command-line-quick-tips-more-about-permissions/"},{default:s(()=>[...e[8]||(e[8]=[o("https://fedoramagazine.org/command-line-quick-tips-more-about-permissions/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=o("作者：",-1)),i(d,{href:"https://fedoramagazine.org/author/pfrields/"},{default:s(()=>[...e[10]||(e[10]=[o("Paul W. Frields",-1)])]),_:1}),e[15]||(e[15]=o(" 选题：",-1)),i(d,{href:"https://github.com/lujun9972"},{default:s(()=>[...e[11]||(e[11]=[o("lujun9972",-1)])]),_:1}),e[16]||(e[16]=o(" 译者：",-1)),i(d,{href:"https://github.com/wxy"},{default:s(()=>[...e[12]||(e[12]=[o("wxy",-1)])]),_:1}),e[17]||(e[17]=o(" 校对：",-1)),i(d,{href:"https://github.com/wxy"},{default:s(()=>[...e[13]||(e[13]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[20]||(e[20]=o("本文由 ",-1)),i(d,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[18]||(e[18]=[o("LCTT",-1)])]),_:1}),e[21]||(e[21]=o(" 原创编译，",-1)),i(d,{href:"https://linux.cn/"},{default:s(()=>[...e[19]||(e[19]=[o("Linux中国",-1)])]),_:1}),e[22]||(e[22]=o(" 荣誉推出",-1))])])}const C=n(c,[["render",u]]);export{x as __pageData,C as default};
